        map["It's fairly warm, but I'd like it to be warmer."] = "C'est assez tiède, mais j'aimerais que ce soit plus chaud.";
        map["Ah, that's better!"] = "Ah, c'est nettement mieux !";
        map["It's a delivery system, I'd imagine it links to the other rooms in the house."] = "C'est un système de livraison pneumatique, il doit communiquer avec les autres pièces.";
        map["I can send items to Arthur and Diana with this."] = "Je peux expédier des objets à Arthur et Diana grâce à ça.";
        map["Ah, there's a package ready to be requested."] = "Ah, une capsule attend d'être réceptionnée.";
        map["The rope is connected to the chandelier hoist."] = "La corde est reliée au treuil du lustre.";
        map["It's keeping the chandelier attached to the ceiling."] = "Elle maintient le lustre suspendu au plafond.";
        map["That rope helps suspend the chandelier from the ceiling."] = "Cette corde retient le lustre au plafond.";
        map["Lady Unterwald must have disapproved of this likeness."] = "Lady Unterwald a dû désapprouver cette ressemblance.";
        map["I remember that was a particularly wrinkly piece."] = "Je me souviens que cette statue était particulièrement fripée.";
        map["It's a big wheel of Parmesan!"] = "C'est une gigantesque meule de parmesan !";
        map["That's a dozen eggs."] = "Voilà une douzaine d'œufs.";
        map["It's a huge sack of flour."] = "C'est un énorme sac de farine.";
        map["Those are some beautiful baguettes."] = "Voilà de bien jolies baguettes.";
        map["There's a tantalising selection of fruit compotes, jellies and relishes."] = "Il y a un assortiment alléchant de compotes de fruits, gelées et condiments.";
        map["It seems like we're well stocked on pickles."] = "On dirait que les réserves de cornichons ne manquent pas.";
        map["I'll bet you could put a lot of meat in there!"] = "Je parie qu'on pourrait entasser un paquet de viande là-dedans !";
        map["The boxes seem to be filled with popcorn."] = "Les cartons semblent remplis de maïs soufflé.";
        map["It's a great loose-fill packaging material, you know!"] = "C'est un excellent matériau de calage pour les colis, vous savez !";
        map["It's also the cheapest thing we could find."] = "C'est aussi ce qu'on a trouvé de moins cher sur le marché.";
        map["It's a pile of recalled Herman Merman merchandise. "] = "C'est un stock de produits dérivés Herman Merman rappelés d'urgence.";
        map["It's a pile of recalled Herman Merman merchandise."] = "C'est un stock de produits dérivés Herman Merman rappelés d'urgence.";
        map["Closer to a towering stack, if you ask me!"] = "Une véritable montagne d'invendus, si vous voulez mon avis !";
        map["I was thinking it's more of a monument to rejection."] = "Je dirais plutôt que c'est un monument érigé au rejet du public.";
        map["Thanks for the input."] = "Merci pour votre contribution.";
        map["I have a great deal of sympathy for the pigeon."] = "J'éprouve une profonde sympathie pour ce pigeon.";
        map["Misunderstood, not particularly popular, considered a nuisance more than anything."] = "Incompris, mal aimé, considéré avant tout comme une nuisance publique.";
        map["You know, a lot of our focus testing said the same thing about you, Herman."] = "Vous savez, Herman, nos panels de lecteurs ont dit exactement la même chose de vous.";
        map["This board is the only thing standing between me and my next published work!"] = "Ce comité éditorial est le seul obstacle entre moi et mon prochain chef-d'œuvre publié !";
        map["I'll need to disable it, somehow."] = "Je dois les neutraliser d'une manière ou d'une autre.";
        map["Looks like you'll be out of commission for a while."] = "On dirait que vous êtes hors d'état de nuire pour un bon moment.";
        map["GRAAAAAGHHH!"] = "GRAAAAAGHHH !";
        map["It's a handy slot for receiving manuscripts."] = "C'est une fente bien pratique pour déposer les manuscrits.";
        map["The paste has hardened and completely filled the inside."] = "La colle a durci et a entièrement colmaté le mécanisme.";
        map["I don't think it'll be taking any more manuscripts."] = "Je doute qu'elle accepte le moindre manuscrit désormais.";
        map["It certainly looks refreshing."] = "Ça a l'air bien désaltérant.";
        map["We infuse the water with a hint of lemon, you know!"] = "Nous infusons l'eau avec une larme de citron, figurez-vous !";
        map["I'm assuming this doubles as the ‘Out' tray."] = "J'imagine que cela fait aussi office de corbeille de rejet.";
        map["There's a rejected manuscript in here already."] = "Il y a déjà un manuscrit recalé là-dedans.";
        map["I don't need to call anyone right now."] = "Je n'ai personne à appeler pour le moment.";
        map["I see a letter opener, and a mini stapler."] = "J'aperçois un ouvre-lettres et une mini-agrafeuse.";
        map["What does he have that I haven't got?"] = "Qu'a-t-il de plus que moi, au juste ?";
        map["An adoring fanbase?"] = "Un public admirateur ?";
        map["Critical acclaim?"] = "Les louanges unanimes de la critique ?";
        map["Upper body strength?"] = "Des muscles dans le haut du corps ?";
        map["One crank of that lever and the board will spring into action."] = "Un tour de manivelle et le comité se mettra en branle.";
        map["Another typically overcast day in London."] = "Encore une journée typiquement maussade à Londres.";
        map["Eugh."] = "Beurk.";
        map["These boxes likely contain manuscripts from my peers."] = "Ces cartons contiennent sûrement des manuscrits de mes confrères.";
        map["Those goons really did a number on Don's door."] = "Ces brutes ont salement amoché la porte de Don.";
        map["The lock on this panel looks quite flimsy."] = "Le verrou de ce panneau semble bien fragile.";
        map["I don't want it back after little mouse paws have been all over it."] = "Je n'en veux plus après que des pattes de rongeur ont crapahuté dessus.";
        map["Perhaps now is not a good time to confront my nyctophobia."] = "Ce n'est peut-être pas le moment idéal pour affronter ma nyctophobie.";
        map["I might be in trouble here!"] = "Je crois que j'ai de gros soucis !";
        map["I was hoping those shots were blanks!"] = "J'espérais que c'étaient des balles à blanc !";
        map["I don't think the train is insured for battle damage!"] = "Je doute que le train soit assuré contre les tirs de combat !";
        map["At least I'm getting some fresh air!"] = "Au moins, je prends un peu l'air frais !";
        map["Ugh, your optimism is nauseating!"] = "Pouah, ton optimisme me donne des hauts-le-cœur !";
        map["I really don't think you should be burning these!"] = "Je ne pense vraiment pas que vous devriez brûler ça !";
        map["Don't look in there! T-They're not important!"] = "Ne regardez pas là-dedans ! C-ce n'est rien d'important !";
        map["I think I managed to salvage some of them."] = "Je crois que j'ai réussi à en sauver une partie.";
        map["I hope Diana is having better luck than me."] = "J'espère que Diana a plus de veine que moi.";
        map["I think this controls the whistle."] = "Je crois que ceci actionne le sifflet du train.";
        map["It's a mess of levers, and nothing is marked!"] = "C'est un embrouillamini de manettes sans la moindre étiquette !";
        map["This looks like a pressure gauge?"] = "On dirait un manomètre de pression ?";
        map["I wasn't trained for this!"] = "On ne m'a pas formée pour piloter une motrice !";
        map["I'm not sure what these do."] = "Je ne sais pas trop à quoi servent ces cadrans.";
        map["I hope Arthur is alright back there."] = "J'espère qu'Arthur s'en sort derrière.";
        map["Those papers really went up in flames!"] = "Ces documents sont partis en fumée en un clin d'œil !";
        map["That's odd, has this been moved recently?"] = "C'est curieux, a-t-on déplacé ceci récemment ?";
        map["The rug? I don't believe so."] = "Le tapis ? Je ne pense pas.";
        map["It wasn't like Lady Unterwald to leave things out of place."] = "Ce n'était pas dans les habitudes de Lady Unterwald de laisser traîner les choses de travers.";
        map["Aha, a hidden hatch."] = "Aha, une trappe secrète.";
        map["Careful, Arthur. We don't know what we're dealing with here."] = "Prudence, Arthur. Nous ignorons ce à quoi nous avons affaire.";
        map["A hidden safe!"] = "Un coffre-fort dissimulé !";
        map["Why would Lady Unterwald need to hide something like this?"] = "Pourquoi Lady Unterwald éprouverait-elle le besoin de cacher un tel coffre ?";
        map["In hindsight, Lady Unterwald was right to have trust issues."] = "Avec le recul, Lady Unterwald avait bien raison d'être méfiante.";
        map["The safe could hold the answers we're looking for, Arthur."] = "Ce coffre pourrait renfermer toutes les réponses que nous cherchons, Arthur.";
        map["Hmm. But how do we get inside?"] = "Hmm. Mais comment l'ouvrir ?";
        map["The safe has two locking mechanisms."] = "Le coffre possède deux mécanismes de verrouillage distincts.";
        map["Sorry I ruined the portrait, Lady Unterwald."] = "Navré d'avoir esquinté votre portrait, Lady Unterwald.";
        map["It all happened so fast."] = "Tout s'est passé si vite.";
        map["If only you were as fast at opening windows, dear."] = "Si seulement vous aviez été aussi prompt à ouvrir les fenêtres, mon cher.";
        map["I've never been painted before. It all happened so fast."] = "On ne m'avait jamais tiré le portrait. Tout est arrivé si vite.";
        map["There's something in his hand, but it's clenched too tight!"] = "Il tient quelque chose dans sa main, mais son poing est trop serré !";
        map["This looks like a listening device. Could this lock be voice activated?"] = "On dirait un récepteur audio. Ce verrou serait-il à commande vocale ?";
        map["Looks like I'll need to input a six-digit number."] = "On dirait que je vais devoir saisir un code à six chiffres.";

        // --- CHAR INTERACTIONS ---
        map["April!"] = "April !";
        map["What is it, Diana?"] = "Qu'y a-t-il, Diana ?";
        map["Found something to break those bars yet?"] = "Tu as trouvé de quoi plier ces barreaux ?";
        map["Arthur?"] = "Arthur ?";
        map["I think I could get a hand free. I'll give it a try!"] = "Je crois que je peux libérer une main. Je vais tenter le coup !";
        map["I'm a little concerned about Dirk Chiselton."] = "Je suis un peu inquiet au sujet de Dirk Chiselton.";
        map["It couldn't hurt to look around."] = "Ça ne coûte rien de jeter un coup d'œil.";
        map["Come on, we have to stop her!"] = "Vite, nous devons l'arrêter !";
        map["Is this the Dirk Chiselton Hotline?"] = "C'est bien la ligne directe de Dirk Chiselton ?";
        map["Yes, I'm a little stuck and I need some answers!"] = "Oui, je suis dans l'impasse et j'ai besoin d'éclaircissements !";
        map["It's quite a sensitive matter."] = "C'est une affaire éminemment délicate.";
        map["Excuse me, this is a private conversation!"] = "Pardonnez-moi, mais c'est une conversation privée !";
        map["I think she's busy."] = "Je crois qu'elle est occupée.";
        map["Oops, sorry."] = "Oups, pardon.";
        map["I'd rather not eavesdrop any further."] = "Je préfère ne pas indiscrètement écouter davantage.";
        map["Let me know when you have all the details."] = "Faites-moi signe quand vous aurez tous les détails.";
        map["Do you remember the gesture the idol was making?"] = "Vous souvenez-vous du geste que faisait l'idole ?";
        map["Alright, I'll keep that in mind."] = "Très bien, je garde cela en mémoire.";
        map["We still need to be sure we have the right idol. Was there any inscription on it?"] = "Nous devons encore nous assurer de tenir la bonne idole. Portait-elle une inscription ?";
        map["Hmm, let's see here..."] = "Hmm, voyons voir par là...";
        map["No luck, I'm afraid."] = "Chou blanc, j'en ai bien peur.";
        map["I had a look, but I can't find an idol that matches your description."] = "J'ai cherché partout, mais aucune idole ne correspond à ce signalement.";
        map["Perhaps you've misremembered some of the details?"] = "Peut-être avez-vous confondu certains détails ?";
        map["Wait a minute. What's this?"] = "Une minute... Qu'avons-nous là ?";
        map["Aha! I think I've got it!"] = "Aha ! Je crois que je l'ai !";
        map["You've found it?"] = "Vous l'avez trouvée ?";
        map["Have a look, the ''All-Hands Meeting'' Idol. It's exactly as you described."] = "Regardez : l'Idole de l'Assemblée Plénière. Elle est exactement comme vous l'avez décrite.";
        map["Took a bit of searching, I tell ya! It'd fallen behind a few palettes of industrial grade moisturiser."] = "Ça m'a pris du temps, je ne vous dis que ça ! Elle était tombée derrière trois palettes de crème hydratante industrielle.";
        map["No, that's not it."] = "Non, ce n'est pas ça.";
        map["Nothing but junk in this pile!"] = "Rien que de la camelote dans ce tas !";
        map["No! Nope! Nada! That's not it, either!"] = "Non ! Pas ça ! Que dalle ! Ce n'est pas ça non plus !";
        map["I don't even know what this thing is!"] = "Je ne sais même pas ce que peut bien être ce machin !";
        map["What's that doing here?"] = "Qu'est-ce que ce truc fiche là ?";
        map["Hello, gentlemen."] = "Bonjour, messieurs.";
        map["Who's this guy?"] = "C'est qui ce type ?";
        map["No idea. He wasn't on the guest list."] = "Aucune idée. Il n'était pas sur la liste des invités.";
        map["I'm looking for someone. Did you see Mr Liu come in here?"] = "Je cherche quelqu'un. Avez-vous vu entrer M. Liu par ici ?";
        map["Jian? Yeah, he was here."] = "Jian ? Ouais, il était là.";
        map["Said he needed to adjust something backstage."] = "Il disait devoir ajuster un détail en coulisses.";
        map["Can we help you with something?"] = "On peut vous aider ?";
        map["May I join you?"] = "Puis-je me joindre à vous ?";
        map["Of course, take a seat."] = "Bien sûr, prenez un siège.";
        map["This many?"] = "Tout ça ?";
        map["Oh goodness!"] = "Bonté divine !";
        map["Just a moment."] = "Un instant.";
        map["They seem busy."] = "Ils ont l'air occupés.";
        map["Yes, Arthur?"] = "Oui, Arthur ?";
        map["I'm sorry about your mission going sideways."] = "Je suis navré que ta mission ait tourné au vinaigre.";
        map["It's not over yet, Arthur. We can still pull this off!"] = "Ce n'est pas encore fini, Arthur. On peut encore réussir le coup !";
        map["What's the plan?"] = "Quel est le plan ?";
        map["First things first, we should take a look around."] = "Chaque chose en son temps : commençons par observer les environs.";
        map["We should help, we can't let them get away!"] = "Nous devons intervenir, on ne peut pas les laisser filer !";
        map["Diana Osterhagen. Pleased to finally make your acquaintance."] = "Diana Osterhagen. Ravie de faire enfin votre connaissance.";
        map["Lovely to meet you, Miss Osterhagen."] = "Enchanté de vous rencontrer, mademoiselle Osterhagen.";
        map["I'm Arthur Ackerman."] = "Je suis Arthur Ackerman.";
        map["It's a terrible shock about Lady Unterwald. That wasn't part of the plan."] = "C'est un choc terrible pour Lady Unterwald. Cela ne faisait pas partie du plan.";
        map["Plan?"] = "Du plan ?";
        map["Still, I was surprised at the low turnout for her announcement."] = "Tout de même, j'ai été surprise de la faible affluence pour son discours.";
        map["Oh, well I'm afraid Lady Unterwald was estranged from her family."] = "Oh, eh bien je crains que Lady Unterwald ne fût en froid avec ses proches.";
        map["I heard her personal lawyer kept writing them out of the inheritance."] = "J'ai ouï dire que son notaire personnel s'évertuait à les déshériter à chaque révision.";
        map["Ah, well..."] = "Ah, eh bien...";
        map["Listen, we shouldn't talk here."] = "Écoutez, nous ne devrions pas parler ici.";
        map["We shouldn't?"] = "Vraiment ?";
        map["I'm all for exchanging pleasantries, but there's too many eyes on us."] = "Je veux bien papoter amicalement, mais il y a trop d'yeux braqués sur nous.";
        map["There are?"] = "Ah bon ?";
        map["Take this, follow the instructions and meet me at the rendezvous."] = "Prenez ceci, suivez les instructions et rejoignez-moi au point de rendez-vous.";
        map["If we have business to discuss, we'll discuss it there."] = "Si nous avons des affaires à régler, nous le ferons là-bas.";
        map["A napkin? Is there something on my face?"] = "Une serviette ? J'ai une tache sur le visage ?";
        map["You said something about a plan?"] = "Vous parliez d'un plan ?";
        map["Trust me, that napkin has everything you need."] = "Croyez-moi, cette serviette contient toutes les indications nécessaires.";
        map["I have some questions."] = "J'ai quelques questions.";
        map["Alright, but you'd better make it quick."] = "D'accord, mais faites vite.";
        map["What sort of favour are we talking about?"] = "De quel genre de service parle-t-on ?";
        map["There's a large, bearded guy in the dining carriage. Mr Masson, you can't miss him."] = "Il y a un grand barbu dans le wagon-restaurant. M. Masson, impossible de le rater.";
        map["He's got something I need for my latest job, but the fool's been holding out."] = "Il a un truc dont j'ai absolument besoin pour mon prochain coup, mais cet imbécile fait de la résistance.";
        map["I need you to take it off his hands and get it back for me."] = "J'ai besoin que vous le lui soutiriez et que vous me le rapportiez.";
        map["But I didn't-"] = "Mais je n'ai pas-";
        map["Relax, okay? We're drinking from the same bottle. They got me on a load of baloney too."] = "Détendez-vous, d'accord ? On est logés à la même enseigne. Ils m'ont coffré pour des prunes aussi.";
        map["Listen, we can't stand around yacking all day, alright? We need to figure a way outta here!"] = "Écoutez, on ne va pas passer la journée à tailler une bavette ! On doit trouver une issue de secours !";
        map["Could you forge a more convincing detective badge out of this toy?"] = "Pourriez-vous me fabriquer un insigne de détective plus convaincant avec ce jouet ?";
        map["Ah, you've got a scheme already cooking I see!"] = "Ah, je vois qu'une petite combine est déjà en train de mijoter !";
        map["Let me take a look at that, see what we're working with here."] = "Faites voir ça, voyons un peu ce qu'on peut en tirer.";
        map["Yeah, I see the problem. You're not fooling anyone with this at a glance."] = "Ouais, je vois le topo. Vous ne berneriez pas un aveugle avec ce truc au premier coup d'œil.";
        map["Just a second, let me work my magic!"] = "Une seconde, je vais faire parler mon talent d'artiste !";
        map["A lick of paint here..."] = "Un coup de pinceau par-ci...";
        map["Bit of polish there..."] = "Un brin de cirage par-là...";
        map["Listen, this'll be enough to get your foot in the door."] = "Écoutez, ce sera suffisant pour forcer le passage.";
        map["Just don't let them look too long at it, alright?"] = "Évitez juste qu'ils s'y attardent trop longtemps, compris ?";
        map["It turns out those twins can be pretty agile when they want to be."] = "Il s'avère que ces jumeaux savent être plutôt agiles quand ils s'en donnent la peine.";
        map["Indeed..."] = "En effet...";
        map["I'm afraid there's not much I can do from over here."] = "J'ai bien peur de ne pas pouvoir faire grand-chose depuis mon emplacement.";
        map["Dirk Chiselton, my arch nemesis."] = "Dirk Chiselton, mon pire rival.";
        map["What do you think of this?"] = "Que dites-vous de cela ?";
        map["Step aside, detective coming through."] = "Place, laissez passer le détective.";
        map["How can I be of service, detective?"] = "Comment puis-je vous rendre service, détective ?";
        map["Herman, how can I help?"] = "Herman, que puis-je pour vous ?";
        map["How low will you go? How high will you jump?"] = "Jusqu'où descendrez-vous ? Jusqu'où sauterez-vous ?";
        map["Aren't your eyes open? Are you not wide awake?"] = "Vos yeux ne sont-ils pas ouverts ? N'êtes-vous pas bien éveillé ?";
        map["You need to climb lightly, be careful not to slip."] = "Montez d'un pas agile, veillez à ne point glisser.";
        map["Are you watching closely? Did you see me make my move?"] = "Observez-vous avec attention ? Avez-vous vu mon geste secret ?";
        map["Jimmy?"] = "Jimmy ?";
        map["Lamont told me not to talk to you, Mr Ackerman!"] = "Lamont m'a formellement interdit de vous adresser la parole, monsieur Ackerman !";
        map["Jimmy!"] = "Jimmy !";
        map["Please, Mr Ackerman! I'm already on thin ice around here."] = "De grâce, monsieur Ackerman ! Je marche déjà sur des œufs ici !";
        map["Let's talk about this!"] = "Parlons-en raisonnablement !";
        map["I'm not allowed to talk to you! Just drop it!"] = "Je n'ai pas le droit de vous parler ! Laissez tomber !";
        map["I'm sure we can work something out?"] = "Je suis sûr qu'on peut s'entendre ?";
        map["La la la la, I can't hear you!"] = "La la la la, je n'entends rien !";
        map["Come on, we're all friends here!"] = "Allons voyons, nous sommes entre amis !";
        map["Mr Ackerman! I really must insist you stop!"] = "Monsieur Ackerman ! J'exige fermement que vous cessiez !";
        map["What's that?!"] = "Qu'est-ce que j'entends ?!";
        map["You'd better not be talking to those prisoners, Jimmy!"] = "Tu ferais bien de ne pas papoter avec ces prisonniers, Jimmy !";
        map["Oh, now you've done it!"] = "Oh bravo, vous avez tout gâché !";
        map["Beat it, pencil-neck. I'm still on break."] = "File d'ici, grand escogriffe. Je suis encore en pause.";
        map["Sorry?"] = "Pardon ?";
        map["I ain't shining shoes right now, you hear me?"] = "Je ne cire aucune pompe pour l'instant, c'est clair ?";
        map["What would you like to trade for your detective kit?"] = "Que voudrais-tu en échange de ton kit de détective ?";
        map["Yeah, like you'd have anything I want."] = "Ouais, comme si vous aviez le moindre truc qui m'intéresse.";
        map["Are you enjoying the script?"] = "Le manuscrit te plaît ?";
        map["Shh! Can't you see I'm reading?"] = "Chut ! Vous voyez pas que je lis ?";
        map["How's the script so far?"] = "Comment trouves-tu l'histoire pour l'instant ?";
        map["Kinda weird, Dirk Chiselton hasn't made an appearance yet."] = "Un peu bizarre, Dirk Chiselton n'a toujours pas fait son apparition.";
        map["Thoughts on the script?"] = "Ton avis sur le récit ?";
        map["It's a lot slower than his last one, he must be building up to a mind-blowing ending!"] = "C'est bien plus mou que son précédent roman, il prépare sûrement une fin explosive !";
        map["Did you have any feedback on that script?"] = "Tu as des remarques sur le texte ?";
        map["I was expecting action, but there's been a lot of talking so far."] = "Je m'attendais à de la bagarre, mais pour l'instant ça ne fait que causer.";
        map["More action?"] = "Plus d'action ?";
        map["Yeah! Getting the bad guys in a headlock and showing them the ol' Hammer and Chisel!"] = "Carrément ! Choper les méchants par le cou et leur balancer le vieux coup du Marteau et du Burin !";
        map["Tackling villains to the ground and giving them a bloody nose! That kind of thing!"] = "Plaquer les truands au sol et leur refaire le portrait ! Ce genre de trucs !";
        map["Ah, well, I'm sure that's all coming right up."] = "Ah, eh bien, je suis certain que ça ne va pas tarder à arriver.";
        map["Let's hope so."] = "On espère bien.";
        map["I didn't mean to flatten him!"] = "Je ne voulais pas l'écraser !";
        map["It was an accident!"] = "C'était un accident !";
        map["Yes, I'm sure you accidentally climbed into the ventilation system for completely innocuous reasons."] = "Oui, je suis convaincue que vous avez escaladé les conduits d'aération pour des motifs parfaitement anodins.";
        map["What's on your mind, Mr Merman?"] = "Qu'avez-vous en tête, monsieur Merman ?";
        map["How can I help, Herman?"] = "Comment puis-je vous aider, Herman ?";
        map["What do you need, Herman?"] = "De quoi avez-vous besoin, Herman ?";
        map["Talk to me, Hermie!"] = "Dis-moi tout, mon petit Hermie !";
        map["How can I help, Hermie?"] = "Que puis-je pour toi, Hermie ?";
        map["Hello, Quartermaster!"] = "Bonjour, l'intendante !";
        map["Mm-hmm. What do you need?"] = "Hum-hum. De quoi as-tu besoin ?";
        map["Wouldn't they have halted the train if someone died?"] = "N'auraient-ils pas arrêté le train si quelqu'un était mort ?";
        map["They don't want to cause panic or suspicion amongst the throng."] = "Ils veulent éviter la panique et la suspicion au milieu de la foule.";
